import os
import asyncio,json,pathlib,datetime,re
from playwright.async_api import async_playwright
async def main():
 async with async_playwright()as p:
  b=await p.chromium.launch(executable_path=os.environ.get('PLAYWRIGHT_CHROMIUM_EXECUTABLE'),args=['--no-sandbox']);page=await b.new_page(viewport={'width':390,'height':844},reduced_motion='no-preference');errors=[];page.on('pageerror',lambda e:errors.append(str(e)));await page.goto(os.environ.get('EXPO_AUDIT_ORIGIN','http://127.0.0.1:8091')+'/workbench?variant=nafas',wait_until='networkidle');await page.get_by_role('button',name='Take a breathing pause',exact=True).click();await page.clock.install();await page.get_by_role('button',name='Start the pause',exact=True).click();await page.clock.run_for(2000);node=page.get_by_test_id('breath-pacing-outline');before=await node.evaluate('(el)=>getComputedStyle(el).transform');value=float(before.split('(')[1].split(',')[0]);assert 1<value<1.17,before;await page.emulate_media(reduced_motion='reduce');await page.clock.run_for(200);after=await node.evaluate('(el)=>getComputedStyle(el).transform');value=float(after.split('(')[1].split(',')[0]);assert value==1,after;await page.get_by_role('button',name='Stop the exercise',exact=True).click();await page.get_by_text('Stopped',exact=True).wait_for();assert not errors,errors
  (pathlib.Path(__file__).resolve().parents[3]/'project/evidence/signature-nafas-motion.json').write_text(json.dumps({'scope':'Actual browser style changes with virtual time, not native FPS, GPU timing or device haptics','normal_motion_mid_inhale_transform':before,'reduced_motion_transform':after,'live_preference_change_stops_motion_without_stopping_the_clock':True,'stoppable_exercise':True,'page_errors':errors,'physical_device_verified':False},indent=2)+'\n');await b.close();print('Normal motion, live reduced-motion change and stop verified.')
asyncio.run(main())
